40	// Per-process handle on the dlopened backend library (libvortex-<NAME>.so).
41	// One backend per process; reused across vx_device_open calls.
42	void*       g_backend_lib = nullptr;
43	callbacks_t g_backend_cb  {};
44	
45	} // anonymous namespace
