49	vx_result_t dispatcher_get_callbacks(const callbacks_t** out) {
50	    if (!out) return VX_ERR_INVALID_VALUE;
51	
52	    if (g_backend_lib != nullptr) {
53	        *out = &g_backend_cb;
54	        return VX_SUCCESS;
55	    }
56	
57	    const char* drv = std::getenv("VORTEX_DRIVER");
58	    if (drv == nullptr) drv = "simx";   // default backend
59	    std::string lib = std::string("libvortex-") + drv + ".so";
60	
61	    void* h = dlopen(lib.c_str(), RTLD_LAZY);
62	    if (h == nullptr) {
63	        std::cerr << "vortex: cannot open backend library '" << lib
64	                  << "': " << dlerror() << std::endl;
65	        return VX_ERR_DEVICE_LOST;
66	    }
67	
68	    using vx_dev_init_t = int (*)(callbacks_t*);
69	    auto init = reinterpret_cast<vx_dev_init_t>(dlsym(h, "vx_dev_init"));
70	    if (init == nullptr) {
71	        std::cerr << "vortex: backend library '" << lib
72	                  << "' is missing vx_dev_init: " << dlerror() << std::endl;
73	        dlclose(h);
74	        return VX_ERR_DEVICE_LOST;
75	    }
76	
77	    if (init(&g_backend_cb) != 0) {
78	        std::cerr << "vortex: vx_dev_init failed in '" << lib << "'"
79	                  << std::endl;
80	        dlclose(h);
81	        return VX_ERR_DEVICE_LOST;
82	    }
83	
84	    g_backend_lib = h;
85	    *out = &g_backend_cb;
86	    return VX_SUCCESS;
87	}
