61	  callbacks->cp_reg_write = [](void* dev_ctx, uint32_t off,
62	                               uint32_t value) -> int {
63	    if (nullptr == dev_ctx)
64	      return -1;
65	    return reinterpret_cast<vx_device*>(dev_ctx)->cp_reg_write(off, value);
66	  };
