69	                              uint32_t* out_value) -> int {
70	    if (nullptr == dev_ctx || nullptr == out_value)
71	      return -1;
72	    return reinterpret_cast<vx_device*>(dev_ctx)->cp_reg_read(off, out_value);
73	  };
