75	  // ----- CP-visible host memory -----
76	  callbacks->host_mem_alloc = [](void* dev_ctx, uint64_t size,
77	                                 void** out_host_ptr,
78	                                 uint64_t* out_cp_addr) -> int {
79	    if (nullptr == dev_ctx || nullptr == out_host_ptr ||
80	        nullptr == out_cp_addr || 0 == size)
