14	// ============================================================================
15	// OPAE backend — a pure transport HAL (see callbacks.h). It exposes only:
16	//   * device lifecycle      — init() / ~vx_device()
17	//   * CP register channel   — cp_reg_read / cp_reg_write
18	//   * CP-visible host memory — host_mem_alloc / host_mem_free
19	//
20	// Device-memory allocation, DMA and capability decoding all live in the
21	// common core; the Command Processor is the sole memory engine. Host memory
22	// is the command ring + DMA staging — a CCI-P-shared buffer (fpgaPrepareBuffer)
23	// reached by the CP's CCI-P host bridge.
24	// ============================================================================
25	
26	#include <common.h>
27	
28	#include "driver.h"
29	
30	#include <vortex_opae.h>
31	
32	#ifdef SCOPE
33	#include "scope.h"
34	#endif
35	
36	#include <cstdlib>
37	#include <cstring>
38	#include <map>
39	#include <stdio.h>
40	#include <stdlib.h>
41	#include <uuid/uuid.h>
42	
43	using namespace vortex;
44	
45	#define MMIO_SCOPE_READ  (AFU_IMAGE_MMIO_SCOPE_READ * 4)
46	#define MMIO_SCOPE_WRITE (AFU_IMAGE_MMIO_SCOPE_WRITE * 4)
47	
48	// ----- Command Processor regfile (host byte addresses) -----
49	// The AFU's MMIO demux routes byte addresses 0x1000..0x1FFF to the CP
50	// regfile (mapped to CP's native 0x000-based 12-bit address space).
51	// Callers pass the CP-internal offset; cp_reg_* add this base.
52	#define CP_BASE              0x1000
53	
54	#define CHECK_FPGA_ERR(_expr, _cleanup)                                        \
55	  do {                                                                         \
56	    auto err = _expr;                                                          \
57	    if (err == 0)                                                              \
58	      break;                                                                   \
59	    printf("[VXDRV] Error: '%s' returned %d, %s!\n", #_expr, (int)err,         \
60	           api_.fpgaErrStr(err));                                              \
61	    _cleanup                                                                   \
62	  } while (false)
63	
64	///////////////////////////////////////////////////////////////////////////////
65	
66	class vx_device {
67	public:
68	  vx_device()
69	    : fpga_(nullptr)
70	  {}
71	
72	  ~vx_device() {
73	  #ifdef SCOPE
74	    vx_scope_stop(this);
75	  #endif
76	    if (fpga_ != nullptr) {
77	      for (auto& kv : host_bos_)
78	        api_.fpgaReleaseBuffer(fpga_, kv.second.wsid);
79	      host_bos_.clear();
80	      api_.fpgaClose(fpga_);
81	    }
82	    drv_close();
83	  }
84	
85	  int init() {
86	    fpga_token accel_token;
87	    fpga_properties filter;
88	    fpga_guid guid;
89	    uint32_t num_matches;
90	
91	    memset(&api_, 0, sizeof(opae_drv_api_t));
92	    if (drv_init(&api_) != 0) {
93	      return -1;
94	    }
95	
96	    // Set up a filter that will search for an accelerator
97	    CHECK_FPGA_ERR(api_.fpgaGetProperties(nullptr, &filter), {
98	      return -1;
99	    });
100	
101	    CHECK_FPGA_ERR(api_.fpgaPropertiesSetObjectType(filter, FPGA_ACCELERATOR), {
102	      api_.fpgaDestroyProperties(&filter);
103	      return -1;
104	    });
105	
106	    // Add the desired UUID to the filter
107	    uuid_parse(AFU_ACCEL_UUID_S, guid);
108	    CHECK_FPGA_ERR(api_.fpgaPropertiesSetGUID(filter, guid), {
109	      api_.fpgaDestroyProperties(&filter);
110	      return -1;
111	    });
112	
113	    // Do the search across the available FPGA contexts
114	    CHECK_FPGA_ERR(api_.fpgaEnumerate(&filter, 1, &accel_token, 1, &num_matches), {
115	      api_.fpgaDestroyProperties(&filter);
116	      return -1;
117	    });
118	
119	    // Not needed anymore
120	    CHECK_FPGA_ERR(api_.fpgaDestroyProperties(&filter), {
121	      api_.fpgaDestroyToken(&accel_token);
122	      return -1;
123	    });
124	
125	    if (num_matches < 1) {
126	      fprintf(stderr, "[VXDRV] Error: accelerator %s not found!\n", AFU_ACCEL_UUID_S);
127	      api_.fpgaDestroyToken(&accel_token);
128	      return -1;
129	    }
130	
131	    // Open accelerator
132	    CHECK_FPGA_ERR(api_.fpgaOpen(accel_token, &fpga_, 0), {
133	      api_.fpgaDestroyToken(&accel_token);
134	      return -1;
135	    });
136	
137	    // Done with token
138	    CHECK_FPGA_ERR(api_.fpgaDestroyToken(&accel_token), {
139	      api_.fpgaClose(fpga_);
140	      return -1;
141	    });
142	
143	  #ifdef SCOPE
144	    {
145	      scope_callback_t callback;
146	      callback.registerWrite = [](vx_device_h hdevice, uint64_t value) -> int {
147	        auto device = (vx_device *)hdevice;
148	        return device->api_.fpgaWriteMMIO64(device->fpga_, 0, MMIO_SCOPE_WRITE, value);
149	      };
150	
151	      callback.registerRead = [](vx_device_h hdevice, uint64_t *value) -> int {
152	        auto device = (vx_device *)hdevice;
153	        return device->api_.fpgaReadMMIO64(device->fpga_, 0, MMIO_SCOPE_READ, value);
154	      };
155	
156	      CHECK_ERR(vx_scope_start(&callback, this, -1, -1), {
157	        api_.fpgaClose(fpga_);
158	        return err;
159	      });
160	    }
161	  #endif
162	
163	    return 0;
164	  }
165	
166	  // ----- CP register channel -----
167	  // The AFU's MMIO demux routes host byte offsets 0x1000..0x1FFF to the CP
168	  // regfile (CP-internal 0x000-based offsets). Callers pass the CP-internal
169	  // offset; we add the AFU base here.
170	  int cp_reg_write(uint32_t off, uint32_t value) {
171	    CHECK_FPGA_ERR(api_.fpgaWriteMMIO64(fpga_, 0, CP_BASE + off, value), {
172	      return -1;
173	    });
174	    return 0;
175	  }
176	
177	  int cp_reg_read(uint32_t off, uint32_t* value) {
178	    uint64_t v = 0;
179	    CHECK_FPGA_ERR(api_.fpgaReadMMIO64(fpga_, 0, CP_BASE + off, &v), {
180	      return -1;
181	    });
182	    *value = uint32_t(v);
183	    return 0;
184	  }
185	
186	  // ----- CP-visible host memory (command ring + DMA staging) -----
187	  // A CCI-P-shared host buffer reached by the CP's CCI-P host bridge.
188	  // fpgaPrepareBuffer hands back both the host VA and the IO address.
189	  int host_mem_alloc(uint64_t size, void** host_ptr, uint64_t* cp_addr) {
190	    uint64_t asize = aligned_size(size, CACHE_BLOCK_SIZE);
191	    void*    ptr   = nullptr;
192	    uint64_t wsid  = 0, ioaddr = 0;
193	    CHECK_FPGA_ERR(api_.fpgaPrepareBuffer(fpga_, asize, &ptr, &wsid, 0), {
194	      return -1;
195	    });
196	    CHECK_FPGA_ERR(api_.fpgaGetIOAddress(fpga_, wsid, &ioaddr), {
197	      api_.fpgaReleaseBuffer(fpga_, wsid);
198	      return -1;
199	    });
200	    host_bos_[ioaddr] = host_bo_t{ ptr, wsid };
201	    *host_ptr = ptr;
202	    *cp_addr  = ioaddr;
203	    return 0;
204	  }
205	
206	  int host_mem_free(uint64_t cp_addr) {
207	    auto it = host_bos_.find(cp_addr);
208	    if (it == host_bos_.end())
209	      return -1;
210	    api_.fpgaReleaseBuffer(fpga_, it->second.wsid);
211	    host_bos_.erase(it);
212	    return 0;
213	  }
214	
215	private:
216	
217	  // CCI-P-shared host buffers (CP-visible host memory), keyed by IO address.
218	  struct host_bo_t {
219	    void*    ptr;     // host-side mapping
220	    uint64_t wsid;    // OPAE workspace id
221	  };
222	  std::map<uint64_t, host_bo_t> host_bos_;
