63	#define MMIO_SCP_ADDR 0x28
64	
65	#define CTL_AP_START (1 << 0)
66	#define CTL_AP_DONE (1 << 1)
67	#define CTL_AP_IDLE (1 << 2)
68	#define CTL_AP_READY (1 << 3)
69	#define CTL_AP_RESET (1 << 4)
70	#define CTL_AP_RESTART (1 << 7)
71	
72	// ----- Command Processor regfile -----
73	// The AXI-Lite demux in VX_afu_wrap routes host addresses 0x1000..0x1FFF
74	// to the CP regfile (mapped to CP's native 0x000-based 12-bit address
75	// space). Callers pass the CP-internal offset; cp_reg_* add this base.
76	#define CP_BASE              0x1000     // host-side base of CP regfile
77	
78	#ifdef CPP_API
79	typedef xrt::device xrt_device_t;
80	typedef xrt::ip     xrt_kernel_t;
81	#else
82	typedef xrtDeviceHandle xrt_device_t;
